    String seed(ObjectReference r){if(r==null)return "-";return String.format(Locale.ROOT,"%012x",((LongValue)field((ObjectReference)field(r,"java.util.Random","seed"),"java.util.concurrent.atomic.AtomicLong","value")).value());}
